def transform(grid):
    h,w=len(grid),len(grid[0])
    orig=[row[:] for row in grid]
    centers=[]
    for r in range(1,h-1):
        for c in range(1,w-1):
            if all(orig[rr][cc]==3 for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))):
                centers.append((r,c,orig[r][c]))
    out=[row[:] for row in orig]
    def ray(r,c,dr,dc,color):
        # The adjacent 3 is the object's own arm; pass it, but preserve it.
        i=2
        while 0 <= r+dr*i < h and 0 <= c+dc*i < w:
            rr,cc=r+dr*i,c+dc*i
            if orig[rr][cc]==3:
                break
            out[rr][cc]=color
            i+=1
    for r,c,color in centers:
        for dc in (-1,1): ray(r,c,0,dc,color)
    for r,c,color in centers:
        for dr in (-1,1): ray(r,c,dr,0,color)
    return out
